-- update70 · COMPTE DE DÉMONSTRATION Akno (revue App Store / Google Play, captures des fiches store)
-- Entreprise FICTIVE « Alpes Rénovation Annecy ». Toutes les lignes sont rattachées au seul compte démo de000000-0000-4000-8000-000000000001
-- (identifiants fixes « de000000-… », appels « demo-… ») : aucune autre table ni aucun autre compte n'est touché.
-- Téléphones fictifs (plage ARCEP 06 39 98 xx xx), e-mails en @example.com (domaine réservé RFC 2606) : aucun SMS ni e-mail réel.
-- Envois automatiques coupés : sms_enabled = false, relances_off = true (devis, factures), rappels/avis RDV marqués déjà traités.
-- Idempotent : rejouable sans doublon (ON CONFLICT). Le mot de passe n'est PAS dans ce fichier : remplacez __DEMO_PASSWORD_HASH__
-- par un hash bcrypt (ex. python3 -c "import bcrypt;print(bcrypt.hashpw(b'MOT_DE_PASSE',bcrypt.gensalt(10)).decode())").
-- Les factures émises (numérotation F-AAAA-NNNN, chaîne de hachage) passent par emettre_facture(), comme dans l'app.
begin;
-- 1. compte auth (créé seulement s'il n'existe pas)
  raw_app_meta_data, raw_user_meta_data, confirmation_token, recovery_token, email_change_token_new, email_change, email_change_token_current, phone_change, phone_change_token, reauthentication_token, is_sso_user, is_anonymous)
values ('00000000-0000-0000-0000-000000000000', 'de000000-0000-4000-8000-000000000001', 'authenticated', 'authenticated', 'demo@akno.fr', '__DEMO_PASSWORD_HASH__', now(), now(), now(),
  '{"provider":"email","providers":["email"],"demo":true}', '{"prenom":"Lucas","entreprise":"Alpes Rénovation Annecy","metier":"Rénovation","cgv_version":"2026-11","demo":true}', '', '', '', '', '', '', '', '', false, false)
on conflict (id) do nothing;
values ('de000000-0000-4000-8000-000000000001', 'de000000-0000-4000-8000-000000000001', 'de000000-0000-4000-8000-000000000001', '{"sub":"de000000-0000-4000-8000-000000000001","email":"demo@akno.fr","email_verified":true}', 'email', now(), now(), now())
on conflict (provider_id, provider) do nothing;
-- 2. entreprise (profil artisan)
update public.artisans set prenom = 'Lucas', nom_entreprise = 'Alpes Rénovation Annecy', entreprise_nom = 'Alpes Rénovation Annecy', entreprise_forme = 'SARL',
  entreprise_capital = '10 000 €', entreprise_adresse = '24 avenue de Brogny', entreprise_cp_ville = '74000 Annecy', entreprise_telephone = '06 39 98 00 01', telephone = '06 39 98 00 01',
  entreprise_email = 'contact@alpes-renovation.example.com', entreprise_siret = '99999900600003', entreprise_tva = 'FR32999999006', entreprise_rcs_rm = 'RCS Annecy 999 999 006 (fictif)',
  entreprise_ape = '4339Z', entreprise_metier = 'Rénovation intérieure, plomberie et électricité', entreprise_ei = false, tva_non_applicable = false,
  assurance_nom = 'Assurance décennale (démo)', assurance_numero = 'DEMO-2026-0001', assurance_zone = 'France métropolitaine', assurance_adresse = '1 place de la Démo, 74000 Annecy',
  entreprise_mediateur = 'Médiateur de la consommation (exemple)', devis_validite_jours = 30, delai_paiement_jours = 30, devis_couleur = '#2F6BFF',
  devis_conditions = 'Acompte de 30 % à la signature, solde à la réception des travaux.', devis_mentions = 'Devis gratuit. TVA selon taux applicable.',
  tarifs = '{"deplacement": 45, "diagnostic": 60, "tauxHoraire": 55, "devisGratuit": true, "majorationUrgence": 50, "majorationWeekend": 30, "zoneKm": 25, "entretienChaudiere": 120}'::jsonb,
  horaires = '{"lun": [["08:00", "12:00"], ["13:30", "18:00"]], "mar": [["08:00", "12:00"], ["13:30", "18:00"]], "mer": [["08:00", "12:00"], ["13:30", "18:00"]], "jeu": [["08:00", "12:00"], ["13:30", "18:00"]], "ven": [["08:00", "12:00"], ["13:30", "17:00"]]}'::jsonb,
  message_accueil = 'Bonjour, vous êtes bien chez Alpes Rénovation Annecy. Je suis l''assistante de Lucas, comment puis-je vous aider ?',
  telephone_urgence = '06 39 98 00 02', iban = 'FR76 3000 1007 9412 3456 7890 185', bic = 'BDFEFRPPXXX', sms_enabled = false, rapport_mensuel = false,
  avis_url = 'https://example.com/avis-alpes-renovation', onboarding_done = true, cgv_version = '2026-11', cgv_accepted_at = coalesce(cgv_accepted_at, now())
where id = 'de000000-0000-4000-8000-000000000001';
-- 3. accès complet (offert / testeur, sans Stripe)
values ('de000000-0000-4000-8000-000000000001', 'clients', 'active', 'clients', true, true, now() + interval '5 years', false, now())
on conflict (artisan_id) do update set plan = excluded.plan, status = excluded.status, plan_override = excluded.plan_override, override_reception = true, reception_option = true, current_period_end = excluded.current_period_end, updated_at = now();

-- 4. clients (particuliers, pros, syndic)
-- 5. équipe (aucune invitation envoyée : access_role vide)
-- 6. devis (numérotation 1 à 10 ; relances automatiques coupées)
-- 7. chantiers géolocalisés autour d'Annecy + équipe affectée
-- 8. appels de la réceptionniste IA (résumé + bilan, sans enregistrement audio)
-- 9. agenda : RDV cette semaine et la semaine prochaine (rappels SMS / avis marqués traités : aucun envoi)
-- 10. factures : brouillon puis émission par emettre_facture() (numéro F-AAAA-NNNN, hachage), statut envoyée / payée
select set_config('request.jwt.claims', '{"sub":"de000000-0000-4000-8000-000000000001","role":"authenticated"}', true), set_config('request.jwt.claim.sub', 'de000000-0000-4000-8000-000000000001', true);
select public.emettre_facture('de000000-0010-4000-8000-000000000001') from public.factures where id = 'de000000-0010-4000-8000-000000000001' and numero is null;
select public.emettre_facture('de000000-0010-4000-8000-000000000002') from public.factures where id = 'de000000-0010-4000-8000-000000000002' and numero is null;
select public.emettre_facture('de000000-0010-4000-8000-000000000003') from public.factures where id = 'de000000-0010-4000-8000-000000000003' and numero is null;
select public.emettre_facture('de000000-0010-4000-8000-000000000004') from public.factures where id = 'de000000-0010-4000-8000-000000000004' and numero is null;
select set_config('request.jwt.claims', '', true), set_config('request.jwt.claim.sub', '', true);
update public.factures set statut = 'payee', envoyee_le = coalesce(envoyee_le, now()), payee_le = coalesce(payee_le, now()), mode_paiement = 'virement' where id = 'de000000-0010-4000-8000-000000000001' and statut in ('emise','envoyee');
update public.factures set statut = 'envoyee', envoyee_le = coalesce(envoyee_le, now()) where id = 'de000000-0010-4000-8000-000000000002' and statut = 'emise';
update public.factures set statut = 'payee', envoyee_le = coalesce(envoyee_le, now()), payee_le = coalesce(payee_le, now()), mode_paiement = 'virement' where id = 'de000000-0010-4000-8000-000000000004' and statut in ('emise','envoyee');
-- 11. relances (aucune ne part : relances_off sur les devis/factures démo, SMS désactivés)
commit;
